import DataService from '../../service/DataService'

let leftsearchSchema = [
    {
        fieldName: 'Title',
        fieldType: "text",
        fieldIcon: "fa-file",
        fieldSearchConditionName: ['orders.order_title'],
        isSearch: false,
        value: "",
        listOptions: []
    },
    {
        fieldName: 'Quote Number',
        fieldType: "text",
        fieldIcon: "fa-file",
        fieldSearchConditionName: ['orders.order_number'],
        isSearch: false,
        value: "",
        listOptions: []
    },
    {
        fieldName: 'Vendor Name',
        fieldType: "ddl-check",
        fieldIcon: "fa-file",
        fieldSearchConditionName: ['orders.account_id'],
        isSearch: false,
        value: "",
        listOptions: []
    },
    {
        fieldName: 'Created By',
        fieldType: "ddl-check",
        fieldIcon: "fa-file",
        fieldSearchConditionName: ['orders.created_by'],
        isSearch: false,
        value: "",
        listOptions: []
    }

]


function bindleftCommonSearchdropdown(instance, ModuleName, SubModule, FilterName) {
    debugger
    var vm = instance;
    let productTypeData = [];

    var params = `Type=${FilterName}&Module=${ModuleName}&SubModule=${SubModule}`

    vm.isLoading = true;

    DataService.QuotesListingFieldData(params).then(response => {

        if (response.data !== null) {

            var json = response.data;

            if (FilterName == 'VENDOR_NAME') {
                vm.leftsearchSchema[2].listOptions = json.map((item) => {
                    const container = {};
                    container.name = item.VENDOR_NAME;
                    container.value = item.Vendor_Id.toString();
                    return container;
                })

            }

            if (FilterName == 'CREATED_BY') {
                vm.leftsearchSchema[3].listOptions = json.map((item) => {
                    const container = {};
                    container.name = item.created_by;
                    container.value = item.user_id.toString();
                    return container;
                })

            }


        }
    })

}
export default { leftsearchSchema, bindleftCommonSearchdropdown };