<template>
    <section class="main-content">

        <loader :is-visible="isLoading"></loader>

        <tg-list :IsShowAction="true" ref="tgList" :showCheckBox="false" ModuleName="CRM" SubModuleCode="CRM_QUOTES"
            IdentityColumn="Order_id" HeaderText="Purchase Quotation" :ListData="QuotationData" :HeaderData="Headers"
            :NorecordfoundText="$t('NoRecordfound')" :TotalRecords="TotalRecords" :SearchFields="leftsearchSchema"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchData" :LegendArray="LegendArray"
            :SortExp="SortExp" :SortBy="SortBy" :HeaderButtons="listheaderbuttons" :CurrentPageNumber="PageNumber"
            :widgets="[]" v-on:LeftsearchButtonClick="leftCommonSearch" v-on:PagerButtonClick="pagerMethod"
            
            v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:ActionButtonClick="actionButtonClick"
            v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'status_id'">

                    <a class="px-2 bg-success text-center text-white d-block" v-if="data.row.status_id === 'Active'">
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                    <a class="px-2 bg-primary text-center text-white d-block"
                        v-else-if="data.row.status_id === 'Approved'">
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                    <a class="px-2 bg-danger text-center text-white d-block" v-else>
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                </template>

                <template v-if="data.column.COLUMN_NAME == 'attachment'">

                    <a @click="handleClick(data.row.Order_id)" style="cursor: pointer;" class="single-action">
                        <em class="fa fa-paperclip " aria-hidden="true"></em>
                    </a>
                </template>
            </template>
        </tg-list>

        <QuotationAttachments v-if="ShowQuoteAttachment" v-on:close="ShowQuoteAttachment = false"
            :QuotationId=QuotationId>
        </QuotationAttachments>
    </section>

</template>
<script>


import DataService from '../../service/DataService'

import QuotationAttachments from '../../components/Modal/QuotationAttachments.vue';

import AllQuotationListingSchema from './AllQuotationListingSchema';

export default {

    components: {

        QuotationAttachments
    },

    data() {
        return {
            isCompare: false,
            LegendArray: [],
            ViewList: [],
            isLoading: false,
            leftSearchFields: [],
            userid: null,
            usertype: null,
            searchCondition: '',
            selectedQuoteType: '',
            ddlQuoteType: '',
            Status: '',
            txtquotetitle: '',
            txtquotenumber: '',
            quotationNumberId: '',
            Title: '',
            QuotationType: '',
            quotationDateFrom: '',
            quotationDateTo: '',
            PageNumber: 1,
            PageSize: 10,
            SortBy: '',
            SortExp: '',
            Headers: null,
            noRecord: false,
            TotalRecords: 0,
            StatusListForListing: [],
            IsAnySearch: false,
            souceID: 0,
            QuotationData: null,
            showAddEventModal: false,
            ShowManageView: false,
            showFilter: false,
            showAddEmailTemplate: false,
            appliedFilter: [],
            privilegeParams: null,
            orderIdForConvertToProject: null,
            showQuoteToProjectModal: false,
            ViewListId: '',
            listheaderbuttons: [

                {
                    title: 'Back',
                    iconClass: 'fa fa-arrow-left',
                    callbackfunction: 'Back',
                    additionalClass: '',
                    isdisabled: false,
                    isvisible: true,
                    checkPrivilege: false
                },

            ],
            listActions:
                [
                    {
                        title: 'Edit',
                        href: '/AssetRequisition/AddPurchaseQuotation/{RequisitionId}/{Order_id}',
                        icon: 'fa fa-pencil text-info action-icon',
                        //callbackfunction: 'Edit1',
                        isDisabled: false,
                        additionalSpan: ''
                    },
                    // {
                    //     title: 'View',
                    //     href: 'javascript:void(0)',
                    //     icon: 'fa fa-eye',
                    //     isDisabled: false,
                    //     callbackfunction: 'View1',
                    //     additionalSpan: ''
                    // },
                ],
            leftsearchSchema: AllQuotationListingSchema.leftsearchSchema,
            IsShowManageQuote: false,
            ShowQuoteAttachment: false,
            QuotationId: null,
            searchCondition: '',

        }
    },

    async created() {

        var vm = this;
        vm.userid = vm.GetUserInfo.ID;
        vm.usertype = vm.GetUserInfo.UserType;
        vm.getStatuslistForListing('CRM', 'en');
        AllQuotationListingSchema.bindleftCommonSearchdropdown(vm, 'Purchase','PURCHASE_QUOTATION', 'VENDOR_NAME');
        AllQuotationListingSchema.bindleftCommonSearchdropdown(vm, 'Purchase','PURCHASE_QUOTATION', 'CREATED_BY')

        vm.FetchData();
        
      

    },
    methods: {

        handleClick: function (QuoteId) {

            var vm = this;
            vm.ShowQuoteAttachment = true;
            vm.QuotationId = QuoteId;

            $("#ShowSubModuleFields").modal('show');
            setTimeout(function () {
                $("#ShowSubModuleFields").modal('show');
                setTimeout(function () {
                    vm.SetBootstraptoolTip();
                }, 200);
            }, 1000);
        },
        renderActions(row) {
            var self = this;
            
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Edit':
                        if (row.status_id == 'Active') {
                            action.isVisible = true;
                        } else {
                            action.isVisible = false;
                        }

                        break;


                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        leftCommonSearch: async function (value) {
            debugger
            this.PageNumber = value.PageNumber;
            this.isPaged = 1;
            if (typeof value.searchCondition != 'undefined') {
                this.searchCondition = value.searchCondition;
            }
            else {
                this.searchCondition = "";
            }

             this.FetchData();
        },
        FetchData: function () {
              debugger
            var VueObj = this;
            VueObj.isLoading = true;
            var params = `pageSize=${VueObj.PageSize}&pageNumber=${VueObj.PageNumber}&pageNum=${VueObj.PageNumber}&isPaged=1&sortBy=${VueObj.SortBy}&sortExp=${VueObj.SortExp}&AssetRequisitionId=&searchCondition=${VueObj.searchCondition}`;
            DataService.AllQuotesListing(params).then(function (response) {
                VueObj.isLoading = false;

                if (response.data != null) {

                    VueObj.Headers = response.data.schema;
                    VueObj.Headers.forEach((column) => {
                        column.DISPLAY_NAME = VueObj.$t(column.DISPLAY_NAME ? column.DISPLAY_NAME : column.COLUMN_NAME);
                        column.settings = null;
                        if (column.COLUMN_NAME == 'status_id') {
                            column.settings = {
                                isInSlot: true
                            }
                        }
                        if (column.COLUMN_NAME == 'attachment') {
                            column.settings = {
                                isInSlot: true
                            }
                        }
                        if (column.COLUMN_NAME == 'order_number') {
                            column.settings = {
                                clickEvent: VueObj.clickEventOfColumn,
                                formatter: VueObj.columnDataFormatter
                            }
                        }

                    });

                    if (response.data.data.length > 0) {
                        VueObj.QuotationData = response.data.data;
                        VueObj.QuotationData.forEach((row) => {
                            row.isCheckBoxDisabled = false;
                            row.additionalClass = '';
                            if (row.status_id == 'Closed') {
                                row.isCheckBoxDisabled = true;
                                row.additionalClass = 'warning-bar';
                            }
                            row.rowDetailsUrl = '';
                            if (row.rowDetailsUrl == '') {
                                row.rowDetailsUrl = '/CRM/ViewQuotationDetails/' + row.Order_id + '/CRM/CRM_QUOTES';
                            }
                        })
                        VueObj.TotalRecords = response.data.data[0].total_records;
                        VueObj.TotalPages = Math.ceil(VueObj.TotalRecords / VueObj.PageSize);
                        VueObj.CurrentPage = VueObj.PageNumber;

                    }
                    else {
                        VueObj.noRecord = true;
                        VueObj.QuotationData = [];
                        VueObj.TotalRecords = 0
                    }
                } else {
                    VueObj.noRecord = true;
                    VueObj.QuotationData = [];
                    VueObj.Headers = [];
                    VueObj.TotalRecords = 0
                }
                VueObj.isLoading = false;

            });
        },


        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },
        commonHeaderButtonClick: function (event) {

            switch (event.callbackfunction) {
                case "Back":
                    this.Back();
                    break;

            }
        },
        actionButtonClick() { },
        getStatuslistForListing: function (StatusType, lang) {

            var vm = this;
            var url = "langCode=" + lang + "&statusType=" + StatusType + "&hasglobal=true";

            DataService.statusdropdown(url).then(function (response) {
                if (response.data.status == "Success") {
                    var json = response.data.result;
                    vm.StatusListForListing = json.data;
                }
            });
        },

        Back() {

            this.$router.push(`/AssetRequisition/NewAssetRequisitionListing`);
        },


    },

}
</script>